import csv
tid='d8a9536c-e875-5be1-90c1-dcfdcb016492'
data=[]
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r['timeseries_id']!=tid: continue
        ts=r['timestamp']; date=ts[:10]; hour=int(ts[11:13])
        if '2018-01-05'<=date<='2018-04-07':
            data.append((date,hour,float(r['value'])))
data.sort(key=lambda x:(x[0],x[1]))
# sum of hour-to-hour absolute changes, within each bucket
occ_chg=0.0; unocc_chg=0.0
prev_occ=None; prev_unocc=None
for date,hour,v in data:
    if 8<=hour<=18:
        if prev_occ is not None: occ_chg+=abs(v-prev_occ)
        prev_occ=v; prev_unocc=None
    else:
        if prev_unocc is not None: unocc_chg+=abs(v-prev_unocc)
        prev_unocc=v; prev_occ=None
print('occ change sum', occ_chg, 'unocc change sum', unocc_chg)
print('occupied' if abs(occ_chg)>abs(unocc_chg) else 'unoccupied')
